Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "fold": [
        "% tributos eletricidade",
        "% tributos gasolina"
      ],
      "as": [
        "serie",
        "valor"
      ]
    },
    {
      "filter": "isValid(datum.valor)"
    },
    {
      "calculate": "datum.serie == ''% tributos eletricidade'' ? ''Eletricidade'' : (time(datum[''Mês'']) < time(datetime(2023, 5, 1)) ? ''Gasolina (só federais)'' : ''Gasolina (federais e ICMS)'')",
      "as": "Série"
    }
  ],
  "mark": {
    "type": "line",
    "interpolate": "step-after"
  },
  "encoding": {
    "x": {
      "field": "Mês",
      "type": "temporal",
      "timeUnit": "yearmonth",
      "title": null,
      "axis": {
        "format": "%Y",
        "tickCount": "year",
        "labelAlign": "left",
        "labelPadding": 6,
        "labelOverlap": "greedy"
      }
    },
    "y": {
      "field": "valor",
      "type": "quantitative",
      "title": "% do preço",
      "axis": {
        "format": ".0%",
        "tickCount": 4
      }
    },
    "color": {
      "field": "Série",
      "type": "nominal",
      "scale": {
        "domain": [
          "Eletricidade",
          "Gasolina (federais e ICMS)",
          "Gasolina (só federais)"
        ],
        "range": [
          "#E0B000",
          "#191919",
          "#A19F9D"
        ]
      },
      "legend": {
        "orient": "top",
        "title": null,
        "direction": "horizontal"
      }
    },
    "strokeDash": {
      "condition": {
        "test": "datum[''Série''] == ''Gasolina (só federais)''",
        "value": [
          4,
          3
        ]
      },
      "value": [
        1,
        0
      ]
    },
    "tooltip": [
      {
        "field": "Mês",
        "type": "temporal",
        "timeUnit": "yearmonth",
        "title": "Mês",
        "format": "%b/%Y"
      },
      {
        "field": "Série"
      },
      {
        "field": "valor",
        "title": "% do preço",
        "format": ".1%"
      }
    ]
  }
}'
